import{c as t,Q as a,j as i,m as d}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"federation/getting-started/installation.md","filePath":"federation/getting-started/installation.md","lastUpdated":1779407857000}'),s={name:"federation/getting-started/installation.md"};function n(o,e,r,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="install-the-plugin" tabindex="-1">Install the plugin <a class="header-anchor" href="#install-the-plugin" aria-label="Permalink to &quot;Install the plugin&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cds-data-federation</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The plugin auto-activates on load via <code>cds-plugin.js</code> — no manual wiring in your <code>server.js</code> or <code>package.json</code>.</p><h2 id="peer-dependencies" tabindex="-1">Peer dependencies <a class="header-anchor" href="#peer-dependencies" aria-label="Permalink to &quot;Peer dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Version</th><th>Required?</th></tr></thead><tbody><tr><td><code>@sap/cds</code></td><td><code>&gt;= 8</code></td><td><strong>Yes</strong></td></tr><tr><td><code>@sap-cloud-sdk/http-client</code></td><td><code>^4</code></td><td>Yes, for OData remote services</td></tr><tr><td><code>@sap-cloud-sdk/resilience</code></td><td><code>^4</code></td><td>Yes, for OData remote services</td></tr><tr><td><a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer"><code>cds-caching</code></a></td><td><code>&gt;= 1</code></td><td>Optional — <code>cache.strategy: &#39;response&#39;</code> (default)</td></tr><tr><td><a href="/pipeline/"><code>cds-data-pipeline</code></a></td><td>peer</td><td>Required for <code>@federation.replicate</code> and <code>cache.strategy: &#39;entity&#39;</code></td></tr><tr><td><code>@cap-js/sqlite</code></td><td><code>&gt;= 2</code></td><td>Optional — SQLite target for replicate and entity cache</td></tr></tbody></table><p>The SAP Cloud SDK HTTP client and resilience packages are what CAP uses under the hood for OData remote service calls. If you already have CAP connected to a remote OData service, these are already installed.</p><h2 id="verifying-the-install" tabindex="-1">Verifying the install <a class="header-anchor" href="#verifying-the-install" aria-label="Permalink to &quot;Verifying the install&quot;">​</a></h2><p>Boot your CAP app and look for a line like this in the log:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[cds-data-federation] discovered 3 @federation.* entities</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>That confirms the plugin is active and found annotations. From there, head to <a href="./first-delegation.html">First Delegation</a>.</p><h2 id="node-js-version" tabindex="-1">Node.js version <a class="header-anchor" href="#node-js-version" aria-label="Permalink to &quot;Node.js version&quot;">​</a></h2><p>The plugin requires Node.js 24 or newer (aligned with <code>@sap/cds</code> &gt;= 8 requirements).</p><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><p>The plugin makes no assumptions about your project layout. The only prerequisite is that your remote service is configured in <code>cds.requires</code> (e.g., via a <code>package.json</code>&#39;s <code>cds.requires</code> block or a service binding), following CAP&#39;s <a href="https://cap.cloud.sap/docs/guides/integration/reuse-and-compose#service-integration" target="_blank" rel="noreferrer">Reuse &amp; Compose — Service Integration</a> pattern.</p>',15)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
